import {
    type ts,
    type Shape,
    type Plugin,
    hasDirective,
    isSupportedNode,
    getKindName,
    getUnsupportedKindName,
} from '@servicenow/sdk-build-core'
import type { Project } from '../project'

export class Committer {
    constructor(private readonly project: Project) {}

    async commit(shape: Shape, target: ts.Node, ...plugins: Plugin[]): Promise<void> {
        if (target.wasForgotten()) {
            throw new Error('Tried to commit to a node that was forgotten')
        }

        if (shape.isNoOp()) {
            return
        }

        if (
            hasDirective(target.getSourceFile(), '@fluent-disable-sync-for-file') ||
            hasDirective(target, '@fluent-disable-sync')
        ) {
            return
        }

        const targetShape = await this.project.getTransform().toShape(target)
        if (!targetShape.success) {
            throw new Error(
                `Tried to check for equality before committing, but the target node (${target.getKindName()}) could not be parsed:\n${target.getFullText()}`
            )
        }

        if (targetShape.value.equals(shape) || shape.equals(targetShape.value)) {
            return
        }

        this.decorateNode(target)
        for (const plugin of plugins.length > 0 ? plugins : this.project.getPlugins().toArray()) {
            const result = await plugin.commit(shape, target, this.project.getContext())
            if (result.success) {
                return
            }
        }

        target.replaceWithText(shape.getCode())
    }

    /**
     * Hack the replaceWithText method to prevent plugins from using it to overwrite code that
     * should be protected by the "@fluent-disable-sync" directive.
     */
    private decorateNode(node: ts.Node): void {
        const marker = '$$_fluent_patched_$$'
        if (marker in node) {
            return
        }

        const method = 'replaceWithText'
        const original = node[method]
        const logger = this.project.getLogger()
        Object.defineProperty(node, method, {
            ...Object.getOwnPropertyDescriptor(node, method),
            value(text: string | ts.WriterFunction) {
                for (const descendant of node.getDescendants()) {
                    if (hasDirective(descendant, '@fluent-disable-sync')) {
                        logger.warn(
                            `Changes to "${isSupportedNode(node) ? getKindName(node) : getUnsupportedKindName(node)}" node in file ${node.getSourceFile().getFilePath()} were blocked because the "@fluent-disable-sync" directive was found in one of its descendants.`
                        )
                        return node
                    }
                }

                return original.call(node, text)
            },
        })

        Object.defineProperty(node, marker, { value: true })
        node.getChildren().forEach((child) => this.decorateNode(child))
    }
}
